export function createServerApi(client: ApiClient) {
    return {
        agents: {
            delete: (slug: string, agentId: string) => client.delete<void, ApiErrorResponse>(API_ENDPOINTS.agents.delete(slug, agentId)),
            edit: (slug: string, request: EditAgentRequest) => client.post<ProvisionAgentResponse, ApiErrorResponse>(API_ENDPOINTS.agents.edit(slug), request),
            get: (slug: string, agentId: string) => client.get<AgentDetailsResponse, ApiErrorResponse>(API_ENDPOINTS.agents.get(slug, agentId)),
            list: (slug: string) => client.get<AgentSummaryResponse[], ApiErrorResponse>(API_ENDPOINTS.agents.list(slug)),
        },
        aiConnectionStrings: {
            create: (request: AiConnectionString) => client.post<AiConnectionStringCreatedResponse, ApiErrorResponse>(API_ENDPOINTS.aiConnectionStrings.create, request),
            delete: (name: string) => client.delete<void, ApiErrorResponse | AiConnectionStringDeleteConflictResponse>(API_ENDPOINTS.aiConnectionStrings.delete(name)),
            detail: (name: string) => client.get<AiConnectionString, ApiErrorResponse>(API_ENDPOINTS.aiConnectionStrings.detail(name)),
            list: () => client.get<AiConnectionString[], ApiErrorResponse>(API_ENDPOINTS.aiConnectionStrings.list),
            test: (request: AiConnectionString) => client.post<AiConnectionStringTestResponse, ApiErrorResponse>(API_ENDPOINTS.aiConnectionStrings.test, request),
        },
        aiModels: {
            list: (request: AiModelsRequest) => client.post<AiModelsResponse, ApiErrorResponse>(API_ENDPOINTS.aiModels.list, request),
        },
        apps: {
            aiConnectionStringsList: (slug: string) => client.get<AiConnectionString[], ApiErrorResponse>(API_ENDPOINTS.apps.aiConnectionStringsList(slug)),
            cdcErrors: (slug: string) => client.get<CdcError[], ApiErrorResponse>(API_ENDPOINTS.apps.cdcErrors(slug)),
            cdcGet: (slug: string) => client.get<AppCdcConfigurationResponse, ApiErrorResponse>(API_ENDPOINTS.apps.cdcGet(slug)),
            cdcPerformance: (slug: string) => client.get<CdcPerformanceResponse, ApiErrorResponse>(API_ENDPOINTS.apps.cdcPerformance(slug)),
            delete: (slug: string) => client.delete<void, ApiErrorResponse>(API_ENDPOINTS.apps.delete(slug)),
            detail: (slug: string) => client.get<AppResponse, ApiErrorResponse>(API_ENDPOINTS.apps.detail(slug)),
            list: () => client.get<AppResponse[]>(API_ENDPOINTS.apps.list),
            provisionAgent: (slug: string, request: EditAgentRequest) => client.post<ProvisionAgentResponse, ApiErrorResponse>(API_ENDPOINTS.apps.provisionAgent(slug), request),
            setupTry: (slug: string, request: SetupTryRequest) => client.post<void, ApiErrorResponse>(API_ENDPOINTS.apps.setupTry(slug), request),
            suggestAgent: (slug: string, request: SuggestAgentRequest) => client.post<SuggestAgentResponse, ApiErrorResponse>(API_ENDPOINTS.apps.suggestAgent(slug), request),
        },
        auth: {
            login: (request: LoginRequest) => client.post<AuthStatusResponse, AuthStatusResponse>(API_ENDPOINTS.auth.login, request),
            logout: () => client.post<void>(API_ENDPOINTS.auth.logout),
            status: () => client.get<AuthStatusResponse>(API_ENDPOINTS.auth.status),
        },
        bootstrap: {
            status: () => client.get<BootstrapStatusResponse>(API_ENDPOINTS.bootstrap.status),
        },
        channels: {
            create: (slug: string, request: ProvisionChannelRequest) => client.post<ProvisionChannelResponse, ApiErrorResponse>(API_ENDPOINTS.channels.create(slug), request),
            delete: (slug: string, channelId: string) => client.delete<void, ApiErrorResponse>(API_ENDPOINTS.channels.delete(slug, channelId)),
            list: (slug: string) => client.get<ChannelSummaryResponse[], ApiErrorResponse>(API_ENDPOINTS.channels.list(slug)),
            update: (slug: string, channelId: string, request: UpdateChannelRequest) => client.put<ChannelSummaryResponse, ApiErrorResponse>(API_ENDPOINTS.channels.update(slug, channelId), request),
        },
        chat: {
            stream: (request: ChatRequest) => client.post<void, ApiErrorResponse>(API_ENDPOINTS.chat.stream, request),
        },
        embedLinks: {
            list: (slug: string) => client.get<EmbedLinkSummaryResponse[], ApiErrorResponse>(API_ENDPOINTS.embedLinks.list(slug)),
            mint: (slug: string, request: MintEmbedLinkRequest) => client.post<MintEmbedLinkResponse, ApiErrorResponse>(API_ENDPOINTS.embedLinks.mint(slug), request),
            revoke: (slug: string, token: string) => client.delete<void, ApiErrorResponse>(API_ENDPOINTS.embedLinks.revoke(slug, token)),
        },
        iframe: {
            getCustomization: (slug: string, channelId: string) => client.get<IFrameCustomizationResponse, ApiErrorResponse>(API_ENDPOINTS.iframe.getCustomization(slug, channelId)),
            getDefaultCustomization: (slug: string) => client.get<IFrameDefaultCustomizationResponse, ApiErrorResponse>(API_ENDPOINTS.iframe.getDefaultCustomization(slug)),
            getStyleGuide: (slug: string) => client.get<IFrameStyleGuideResponse, ApiErrorResponse>(API_ENDPOINTS.iframe.getStyleGuide(slug)),
            preview: (slug: string, searchParams?: { title?: string; }) => client.get<IFramePreviewResponse, ApiErrorResponse>(API_ENDPOINTS.iframe.preview(slug), { searchParams }),
            updateCustomization: (slug: string, channelId: string, request: UpdateIFrameCustomizationRequest) => client.put<IFrameCustomizationResponse, ApiErrorResponse>(API_ENDPOINTS.iframe.updateCustomization(slug, channelId), request),
            updateDefaultCustomization: (slug: string, request: UpdateIFrameCustomizationRequest) => client.put<IFrameDefaultCustomizationResponse, ApiErrorResponse>(API_ENDPOINTS.iframe.updateDefaultCustomization(slug), request),
        },
        settings: {
            certificates: (searchParams: { pageSize: string; start: string; }) => client.get<CertificateItem[], ApiErrorResponse>(API_ENDPOINTS.settings.certificates, { searchParams }),
            certificatesEdit: (request: Record<string, DatabaseAccess>, searchParams: { clearance: SecurityClearance; disable: boolean; name: string; thumbprint: string; }) => client.post<void, ApiErrorResponse>(API_ENDPOINTS.settings.certificatesEdit, request, { searchParams }),
            certificatesGenerate: (request: Record<string, DatabaseAccess>, searchParams: { clearance: SecurityClearance; name: string; password?: string; }) => client.post<void, ApiErrorResponse>(API_ENDPOINTS.settings.certificatesGenerate, request, { searchParams }),
            feedback: (request: SendFeedbackRequest) => client.post<void, ApiErrorResponse>(API_ENDPOINTS.settings.feedback, request),
            license: () => client.get<LicenseResponse>(API_ENDPOINTS.settings.license),
            usage: (searchParams: { day?: string; month?: string; year: string; }) => client.get<QuillUsageResponse, ApiErrorResponse>(API_ENDPOINTS.settings.usage, { searchParams }),
        },
        setup: {
            connect: (request: ConnectRequest) => client.post<ConnectResult, ApiErrorResponse>(API_ENDPOINTS.setup.connect, request),
            discover: (request: DiscoverRequest) => client.post<DiscoverResponse, ApiErrorResponse>(API_ENDPOINTS.setup.discover, request),
            map: (request: MapRequest) => client.post<CdcSinkConfiguration, ApiErrorResponse>(API_ENDPOINTS.setup.map, request),
            provision: (request: ProvisionRequest) => client.post<ProvisionResponse, ApiErrorResponse>(API_ENDPOINTS.setup.provision, request),
            suggestCdc: (request: SuggestCdcRequest) => client.post<SuggestCdcResponse, ApiErrorResponse>(API_ENDPOINTS.setup.suggestCdc, request),
            testMapping: (request: TestMappingRequest) => client.post<TestMappingResponse, ApiErrorResponse>(API_ENDPOINTS.setup.testMapping, request),
            verifyCdc: (request: VerifyCdcRequest) => client.post<VerifyCdcResponse, ApiErrorResponse>(API_ENDPOINTS.setup.verifyCdc, request),
        },
        stats: {
            activity: (slug: string) => client.get<ActivityEventDto[], ApiErrorResponse>(API_ENDPOINTS.stats.activity(slug)),
            appUsage: (slug: string, searchParams: { day?: string; month?: string; year: string; }) => client.get<AppUsageResponse, ApiErrorResponse>(API_ENDPOINTS.stats.appUsage(slug), { searchParams }),
            channels: (slug: string) => client.get<ChannelStatsResponse, ApiErrorResponse>(API_ENDPOINTS.stats.channels(slug)),
            collections: (slug: string) => client.get<DataCollectionDto[], ApiErrorResponse>(API_ENDPOINTS.stats.collections(slug)),
            conversation: (slug: string, conversationId: string) => client.get<ConversationDto, ApiErrorResponse>(API_ENDPOINTS.stats.conversation(slug, conversationId)),
            conversations: (slug: string, searchParams: { day?: string; month?: string; pageSize?: string; start?: string; year: string; }) => client.get<ConversationListResult, ApiErrorResponse>(API_ENDPOINTS.stats.conversations(slug), { searchParams }),
            conversationStats: (slug: string, searchParams: { day?: string; month?: string; year: string; }) => client.get<ConversationStatsResponse, ApiErrorResponse>(API_ENDPOINTS.stats.conversationStats(slug), { searchParams }),
            dashboardApp: (slug: string) => client.get<ApplianceAppResponse, ApiErrorResponse>(API_ENDPOINTS.stats.dashboardApp(slug)),
            dashboardApps: () => client.get<ApplianceAppResponse[]>(API_ENDPOINTS.stats.dashboardApps),
            overview: (slug: string) => client.get<AppOverviewResponse, ApiErrorResponse>(API_ENDPOINTS.stats.overview(slug)),
            tokensByApp: () => client.get<TokensByAppResponse>(API_ENDPOINTS.stats.tokensByApp),
            usage: (searchParams: { app?: string; day?: string; month?: string; year: string; }) => client.get<UsageResponse>(API_ENDPOINTS.stats.usage, { searchParams }),
        },
    };
}

export type ServerApi = ReturnType<typeof createServerApi>;
